N = 7
A = []
for r_i in R:
    row = [r_i + c_j for c_j in C]
    A.append(row)

# Check if all 49 elements are distinct
elements = set()
for row in A:
    for x in row:
        if x in elements:
            print("Failure: Duplicate found.")
            exit()
        elements.add(x)

print(f"Total distinct elements found: {len(elements)}")

# Check if the set is {1, 2, ..., 49}
target_set = set(range(1, 50))
if elements == target_set:
    print("Success: The set of sums is exactly {1, 2, ..., 49}.")
else:
    print("Failure: The set of sums is not {1, 2, ..., 49}.")

